"""Versioned instructions shared by the LOHC matrix agents."""

VERSION = 'lohc-three-matrix-v1'
RULES = '''LOHC three-matrix protocol v1. AL describes the hydrogen-lean state; AR describes the hydrogen-rich state. Atom IDs are zero-based and local to each state. Each atom has [atomic_number, formal_charge, H_count, isotope, aromatic_flag]. Each undirected bond uses [i,j,bond_order]; 1.5 denotes aromatic. P.C maps lean atom i to rich atom C(i). P.delta is expressed entirely in lean coordinates. For delta row [i,j,d], find AL(i,j), then AR(C(i),C(j)); order the endpoints before lookup. An omitted bond has order 0. The check is rich_order - lean_order = d. Example: if C(4)=9 and C(7)=2, then [4,7,-0.5] means compare AL(4,7) and AR(2,9), e.g. 1.5 to 1.0. Do not use the lean coordinates directly in AR. The three P property values are theoretical H2 wt%, dehydrogenation enthalpy in kJ/mol H2, and equivalent mapping count. The difference is lean to rich; the enthalpy is rich to lean. Copy properties as supplied; null is unknown. Equivalent mappings are not chemical rearrangements. No stereochemistry is encoded. Base chemical claims on referenced matrix coordinates and applicable evidence. For Search Agent identity resolution, use program-derived structure identifiers when provided.'''

BLOCKS = '''AL and AR have atoms rows [id, atomic_number, formal_charge, H_count, isotope, aromatic_flag] and upper triangular bonds. P contains correspondence rows [lean_id,rich_id], upper triangular delta rows, and properties. If asked to reconstruct SMILES, build AL and AR independently from their own atom and bond tables. Preserve every branch and ring closure, and use aromatic atoms only where the corresponding state indicates aromaticity. Check each proposed SMILES against its own state before returning it.'''

DENSE = '''AL and AR have n rows: the first n columns are bond orders, followed by the five atom labels. In P, the first n rows contain [C | delta | three padding columns]; C is a permutation matrix with lean rows and rich columns. The final P row ends with the three properties. Ignore padding cells.'''

DISPATCH_VERSION = 'lohc-evidence-dispatch-v1'
DISPATCH = '''Dispatch independently for SR (rich-state stability), SL (lean-state stability), SP (conversion), liquid_R and liquid_L. Match the requested endpoint and state before judging similarity. Reuse applicable exact evidence from literature memory. Search missing endpoints with identifiers derived from the matrix. If no reviewed exact result is available, consider reviewed structural analogues with recorded scaffold, similarity and differences. An analogue may support a qualitative hypothesis only. Never copy its enthalpy, melting point, phase, or stability to the target as measured. If no analogue supports the endpoint, make an explicitly structure-only inference or mark the judgment unknown. System decomposition does not establish either state's shelf stability. Reaction in solvent does not establish neat phase. Record both states' observed conditions; a shared liquid window needs compatible evidence for both states. Keep literature memory and scoring memory separate. Store the same three matrices, endpoint grades, provenance, coordinates and protocol version with each accepted score. Reuse only when the inputs, accepted evidence, scoring protocol and model match. A prior model grade is never a literature observation.'''
